  const pinMsg = chatDoc && chatDoc.pinned ? Store.get('msgs', chatDoc.pinned) : null; let pb = c.el.querySelector('.pinbar'); if (pinMsg) { if (!pb) { pb = document.createElement('div'); pb.className = 'pinbar'; box.before(pb); } pb.innerHTML = `<b>Pinned</b> ${esc(Names.of(pinMsg.author))}: ${esc((pinMsg.text || 'photo').slice(0, 90))}`; } else if (pb) pb.remove();
  const lastMine = list.filter(m => m.author === Store.uid).slice(-1)[0]; if (lastMine && chatDoc && chatDoc.kind === 'dm') { const other = arr(chatDoc.members).find(u => u !== Store.uid); if ((reads[other] || 0) >= lastMine.ts) box.insertAdjacentHTML('beforeend', '<p class="seen">Seen</p>'); }
  if (atBottom || !box._init) { box.scrollTop = box.scrollHeight; box._init = 1; }
