  const boosted = q => (q.boostUntil || 0) > now() ? 20 : 0; const deck = pool.filter(q => !decided.has(q.id)).sort((a, b) => boosted(b) + (arr(b.supers).includes(Store.uid) ? 9 : 0) + shared(b) - boosted(a) - (arr(a.supers).includes(Store.uid) ? 9 : 0) - shared(a)); const visitors = visitorsOf(Store.uid);
