  const card = q => `<div class="mcard">${safeUrl(q.avatar) ? `<img src="${esc(safeUrl(q.avatar))}" alt="">` : `<div class="mph" style="background:${esc(AV_COLORS.includes(q.color) ? q.color : '#0f5a43')}">${esc(Names.of(q.id)[0] || '?')}</div>`}<div class="mcinfo"><h2>${esc(Names.of(q.id))}, ${esc(q.age)}</h2><p>${esc(q.city || '')} · looking for ${esc(q.mode === 'both' ? 'friends or dating' : q.mode)}</p>${arr(q.supers).includes(Store.uid) ? '<p class="pill hot">Super-liked you</p>' : ''}<p>${esc(q.bio || '')}</p><p>${arr(q.interests).map(i => `<span class="pill ${arr(p.interests).includes(i) ? 'on' : ''}">${esc(i)}</span>`).join(' ')}</p></div></div>`;
  el.innerHTML = `<section class="band"><div class="libhead"><h1>Match</h1><div class="row-btns"><button class="btn sm" id="boost" ${(p.boostUntil || 0) > now() ? 'disabled' : ''}>${(p.boostUntil || 0) > now() ? 'Boosted for ' + Math.ceil((p.boostUntil - now()) / 60e3) + ' min' : 'Boost my profile'}</button><button class="btn sm" id="rewind" ${arr(LS.get('passStack', [])).length ? '' : 'disabled'}>Rewind last pass</button><button class="btn sm ghost" id="mset">Settings</button></div></div><div class="chips">${[['discover', 'Discover'], ['liked', `Liked you ${likedMe.length}`], ['matches', `Matches ${matches.length}`], ['nearby', 'Nearby'], ['visitors', `Visitors ${visitors.length}`]].map(([k, l]) => `<button class="chip ${tab === k ? 'on' : ''}" data-mt="${k}">${l}</button>`).join('')}</div>
    ${tab === 'discover' ? (deck.length ? `<div class="deck">${card(deck[0])}<div class="mbtns"><button class="btn big" data-sw="pass">Pass</button><button class="btn big" data-sw="super">Super like</button><button class="btn big hot" data-sw="like">Like</button></div><p class="muted small center">${deck.length - 1} more · keys: ← pass, → like, ↑ super like</p></div>` : '<p class="empty">You have seen everyone for now. Check back as more people turn on Match.</p>')
    : tab === 'liked' ? `<div class="people">${likedMe.map(q => `<div class="person">${avatar(q.id, 56)}<div>${nameLink(q.id)}<small>${esc(q.age)} · ${esc(q.city || '')}</small></div><button class="btn sm hot" data-like="${esc(q.id)}">Like back</button><button class="btn sm ghost" data-pass="${esc(q.id)}">Pass</button></div>`).join('') || '<p class="muted">No new likes yet.</p>'}</div>`
    : tab === 'matches' ? `<div class="people">${matches.map(q => `<div class="person">${avatar(q.id, 56)}<div>${nameLink(q.id)}<small>Matched</small></div><button class="btn sm hot" data-chat="${esc(q.id)}">Message</button><button class="btn sm ghost" data-unmatch="${esc(q.id)}">Unmatch</button></div>`).join('') || '<p class="muted">No matches yet. Keep swiping.</p>'}</div>`
    : tab === 'visitors' ? `<div class="people">${visitors.map(v => `<div class="person">${avatar(v.v, 56)}<div>${nameLink(v.v)}<small>viewed you ${ago(v.ts)}</small></div>${friendBtn(v.v)}</div>`).join('') || '<p class="muted">No profile visitors in the last 30 days.</p>'}</div>`
    : `<div class="people">${near.map(q => `<div class="person">${avatar(q.id, 56)}<div>${nameLink(q.id)}<small>${esc(q.age)} · ${esc(q.city)}</small></div>${arr(p.likes).includes(q.id) ? '<span class="pill">Liked</span>' : `<button class="btn sm hot" data-like="${esc(q.id)}">Like</button>`}</div>`).join('') || `<p class="muted">${p.city ? 'No one nearby yet.' : 'Add your city in settings to see people nearby.'}</p>`}</div>`}</section>`;
  $('#boost') && ($('#boost').onclick = async () => { if (!isMember() && LS.get('boostDay') === today()) return toast('Free players get one boost a day. Members can boost any time.'); LS.set('boostDay', today()); await saveMe({ boostUntil: now() + 30 * 60e3 }); toast('Boosted: you are shown first for 30 minutes.'); });
