  el.querySelectorAll('[data-sw]').forEach(b => b.onclick = () => decide(deck[0].id, b.dataset.sw));
  el.onclick = async e => { const b = e.target.closest('button'); if (!b) return; if (b.dataset.like) decide(b.dataset.like, 'like'); if (b.dataset.pass) decide(b.dataset.pass, 'pass'); if (b.dataset.chat) location.hash = 'messages-' + await dmWith(b.dataset.chat); if (b.dataset.unmatch) { await saveMe({ likes: arr(me().likes).filter(x => x !== b.dataset.unmatch), passes: [...new Set(arr(me().passes).concat(b.dataset.unmatch))] }); } };
